import{_ as a,a as s,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Redis HyperLogLog（基数统计）","description":"活动参与人数与近似去重统计，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis HyperLogLog（基数统计）","description":"活动参与人数与近似去重统计，包括基本操作、适用场景和使用边界。","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis 数据类型","summary":"活动参与人数与近似去重统计，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis Bitmap（位图）","link":"/middleware/redis/plus/subjects/bitmap"},"next":{"text":"Redis Geo（地理位置）","link":"/middleware/redis/plus/subjects/geo"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis Bitmap（位图）","link":"/middleware/redis/plus/subjects/bitmap"},"next":{"text":"Redis Geo（地理位置）","link":"/middleware/redis/plus/subjects/geo"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/hyperloglog.md","filePath":"middleware/redis/plus/subjects/hyperloglog.md"}'),r={name:"middleware/redis/plus/subjects/hyperloglog.md"};function n(l,e,d,p,h,o){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="hyperloglog" tabindex="-1">Redis HyperLogLog（基数统计） <a class="header-anchor" href="#hyperloglog" aria-label="Permalink to &quot;Redis HyperLogLog（基数统计） {#hyperloglog}&quot;">​</a></h1><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="position" tabindex="-1">1. 定位：解决什么问题 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;1. 定位：解决什么问题 {#position}&quot;">​</a></h2><p>HyperLogLog 维护集合基数的概率估计，适合活动参与人数、UV、不同 IP 等统计。Set 保存实际成员且精确，HLL 更省内存但不能查询成员、枚举成员或精确删除一个参与者。标准误差约为 0.81%，这是统计特征，不是每次结果的绝对误差上限。</p><h3 id="基本操作示例" tabindex="-1">基本操作示例 <a class="header-anchor" href="#基本操作示例" aria-label="Permalink to &quot;基本操作示例&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PFADD learn:hll:event player-1 player-2 player-1</span></span>
<span class="line"><span>PFCOUNT learn:hll:event</span></span></code></pre></div><p>这是近似去重统计，重复加入同一成员不会按普通计数器累加。示例小集合通常得到 2，但业务不能据此认为任意规模都精确。</p><h3 id="游戏与后端场景" tabindex="-1">游戏与后端场景 <a class="header-anchor" href="#游戏与后端场景" aria-label="Permalink to &quot;游戏与后端场景&quot;">​</a></h3><p>适合统计活动参与人数、网站 UV、广告点击用户、日志中的不同 IP。按活动、日期或区域设计键，例如 <code>event:halloween:participants</code>。需要合并多个分组时，可使用 <code>PFMERGE</code> 或相应多键计数，并确认集群同槽条件。</p><h2 id="commands" tabindex="-1">2. 命令速查与示例 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;2. 命令速查与示例 {#commands}&quot;">​</a></h2><p>按用途分组，共 <strong>5 项</strong>，覆盖 Redis 8.2.10 的本类型命令及子命令。点击命令名查看官方参数。示例在 redis-cli 中逐行输入，<strong>每次换例子前重置下面的教学数据</strong>。</p><details class="details custom-block"><summary>准备与重置示例数据</summary><p>在独立实验实例的 <strong>redis-cli 交互模式</strong>逐行输入，避免 shell 对引号、<code>&gt;</code>、<code>*</code>、括号等符号进行解释。<strong>每个例子独立使用；换例子前重新执行下面的准备段</strong>，否则删除、弹出、过期和修改操作会影响后续结果。准备段仅重置列出的教学键，确认这些键不承载业务数据。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNLINK learn:{hll}:a learn:{hll}:b learn:{hll}:out</span></span>
<span class="line"><span>PFADD learn:{hll}:a player-1 player-2</span></span>
<span class="line"><span>PFADD learn:{hll}:b player-2 player-3</span></span></code></pre></div><p>示例的返回说明以刚完成准备段为前提，随机结果与剩余 TTL 不固定。带同一 <code>{...}</code> 的教学键便于在 Cluster 中满足相关多键操作的同槽要求。</p></details><h3 id="基数统计" tabindex="-1">基数统计 <a class="header-anchor" href="#基数统计" aria-label="Permalink to &quot;基数统计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-pfadd"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/pfadd.json" target="_blank" rel="noopener noreferrer">PFADD</a><br>加入统计对象</td><td><code>PFADD learn:{hll}:a player-3</code><br>返回寄存器是否变化，不代表精确新增人数。</td><td>每个输入元素 O(1)</td></tr><tr><td><span id="cmd-pfcount"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/pfcount.json" target="_blank" rel="noopener noreferrer">PFCOUNT</a><br>估计不同对象数</td><td><code>PFCOUNT learn:{hll}:a</code><br>准备数据的小集合通常估计为 2，但总体是近似结果。</td><td>单键 O(1)<br>多键 O(K)</td></tr><tr><td><span id="cmd-pfmerge"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/pfmerge.json" target="_blank" rel="noopener noreferrer">PFMERGE</a><br>合并多个 HLL</td><td><code>PFMERGE learn:{hll}:out learn:{hll}:a learn:{hll}:b</code><br>返回 OK，out 表示并集估计，不能直接把人数相加。</td><td>O(K)</td></tr></tbody></table><h3 id="内部诊断命令" tabindex="-1">内部诊断命令 <a class="header-anchor" href="#内部诊断命令" aria-label="Permalink to &quot;内部诊断命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-pfdebug"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/pfdebug.json" target="_blank" rel="noopener noreferrer">PFDEBUG</a><br>内部 HLL 诊断入口</td><td><code>PFDEBUG ENCODING learn:{hll}:a</code><br>内部诊断命令，本例查看 sparse/dense；不是稳定业务接口。</td><td>未定义</td></tr><tr><td><span id="cmd-pfselftest"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/pfselftest.json" target="_blank" rel="noopener noreferrer">PFSELFTEST</a><br>内部 HLL 自测</td><td><code>PFSELFTEST</code><br>内部自测可能占用明显 CPU，仅在隔离实验实例按需使用。</td><td>未定义</td></tr></tbody></table><details class="details custom-block"><summary>版本与复杂度补充</summary><p>下表保留每条命令的引入版本、兼容状态及复杂度符号含义；复杂度不包含全部网络传输、内存分配和等待成本。</p><table tabindex="0"><thead><tr><th>命令</th><th>引入版本与状态</th><th>复杂度说明</th></tr></thead><tbody><tr><td><a href="#cmd-pfadd">PFADD</a></td><td>2.8.9</td><td>每个输入元素 O(1)，K 个元素为 O(K)。</td></tr><tr><td><a href="#cmd-pfcount">PFCOUNT</a></td><td>2.8.9</td><td>单键平均 O(1)；K 个键合并为 O(K)，常数较大。</td></tr><tr><td><a href="#cmd-pfmerge">PFMERGE</a></td><td>2.8.9</td><td>O(K)，K 为输入 HLL 数量，合并常数较大。</td></tr><tr><td><a href="#cmd-pfdebug">PFDEBUG</a></td><td>2.8.9；内部系统命令</td><td>官方标为 N/A；内部诊断不提供稳定业务性能承诺。</td></tr><tr><td><a href="#cmd-pfselftest">PFSELFTEST</a></td><td>2.8.9；内部系统命令</td><td>官方标为 N/A；内部诊断不提供稳定业务性能承诺。</td></tr></tbody></table></details><p>通用键操作见<a href="/middleware/redis/base/basic/keys">键与过期时间</a>，这里集中列出类型自身的命令。</p><h2 id="encoding" tabindex="-1">3. 底层编码与内存 <a class="header-anchor" href="#encoding" aria-label="Permalink to &quot;3. 底层编码与内存 {#encoding}&quot;">​</a></h2><p>逻辑 HLL 在 Redis 中存为 String，内部有 sparse/dense 表示；OBJECT ENCODING 看到的是字符串编码，不直接显示 HLL 稀疏/稠密模式。密集寄存器有效载荷约 12 KiB，实际键占用还包括头部和管理开销。</p><p>8.2.10 的 <code>hll-sparse-max-bytes</code> 默认 3000，控制稀疏表示字节预算。超过预算或稀疏格式无法表示时会转为密集形式；不是到固定参与人数就必然转换。</p><h3 id="编码与内存怎么测" tabindex="-1">编码与内存怎么测 <a class="header-anchor" href="#编码与内存怎么测" aria-label="Permalink to &quot;编码与内存怎么测&quot;">​</a></h3><p>在独立实验实例准备教学键，再读实际状态；下列是测量方法，本次未运行或填写测量数字：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PFADD learn:hll:event player-1 player-2</span></span>
<span class="line"><span>OBJECT ENCODING learn:hll:event</span></span>
<span class="line"><span>MEMORY USAGE learn:hll:event</span></span></code></pre></div><p>固定键名、元素字节长度、Redis 版本和分配器，分别记录 1、10、100 个元素或不同值长度时的内存，再跨越编码阈值观察。单元素的增量开销可用相邻两次内存差估计，编码转换时不能套用线性平均；String/Bitmap 的横轴应使用字节数或最高位偏移。比较“一键多元素”和“多个独立键”时，把键名、对象、字典项和 TTL 管理开销一起计入。</p><p>MEMORY USAGE 默认对嵌套值采样，<code>SAMPLES 0</code> 会遍历所有嵌套值，仅在小型隔离实验中使用。其结果不等同于进程 RSS；大量键还会增加全局字典、分配器碎片和复制缓冲等成本，需结合 INFO memory。没有适用于所有版本的固定“每 key 几字节”。</p><p>依据：<a href="https://github.com/redis/redis/blob/8.2.10/redis.conf" target="_blank" rel="noopener noreferrer">8.2.10 配置</a>、<a href="https://github.com/redis/redis/blob/8.2.10/src/hyperloglog.c" target="_blank" rel="noopener noreferrer">对应类型实现</a>、<a href="https://redis.io/docs/latest/commands/memory-usage/" target="_blank" rel="noopener noreferrer">MEMORY USAGE</a>。</p><h2 id="performance" tabindex="-1">4. 性能与阻塞风险 <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;4. 性能与阻塞风险 {#performance}&quot;">​</a></h2><p>PFCOUNT 单键可复用基数缓存，更新后重算与多个 HLL 合并有不同成本。很多键一次 PFCOUNT/PFMERGE 会占用执行时间。HLL 不保存可遍历成员，没有对应 SCAN；若需要查参与者，必须另存精确集合或权威记录。</p><p>常规命令执行主要占用主执行路径，耗时计算会拖慢同实例其他请求；网络 I/O、后台持久化和释放内存有其他线程/进程参与。命令复杂度不包含所有网络、分配、编码转换与客户端成本。</p><h2 id="atomicity" tabindex="-1">5. 原子性与并发 <a class="header-anchor" href="#atomicity" aria-label="Permalink to &quot;5. 原子性与并发 {#atomicity}&quot;">​</a></h2><p>单次 PFADD/PFMERGE 原子，但多次独立 PFCOUNT 后在应用求和不等于并集人数。活动结束的最终统计需要冻结输入或明确截止水位；使用 Lua 也不能消除概率误差。PFADD 的返回值不能决定是否首次发奖。</p><p>MULTI/EXEC 保证排队命令连续执行，但执行时单条报错不会回滚其他已成功命令；WATCH 是乐观冲突检测，需要有界重试。Lua 也不会自动回滚运行错误前的写入，应先校验参数与类型，再修改状态。</p><h2 id="lifecycle" tabindex="-1">6. 过期、持久化与生命周期 <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;6. 过期、持久化与生命周期 {#lifecycle}&quot;">​</a></h2><p>TTL 作用于整个 HLL，不能按成员失效或删除成员。按日/活动分键并保留原始桶，滑动时间窗口对有效桶做并集估计；无法从总 HLL 中减去某一天。PFMERGE 目标属于新统计产物，应显式设计其保留期。</p><p>大键会增加 RDB/AOF 重写、复制全量同步和恢复时的处理量，fork 写时复制还可能增加峰值内存。单次同步删除聚合对象可能阻塞；<code>UNLINK</code> 先摘除键，把主要回收工作移到后台，但总回收工作和内存压力仍存在，不能替代限长和拆分。</p><p>完成教学实验后，只清理自己创建的键，例如 <code>UNLINK learn:hll:event</code>。</p><h2 id="cluster" tabindex="-1">7. 集群与扩展 <a class="header-anchor" href="#cluster" aria-label="Permalink to &quot;7. 集群与扩展 {#cluster}&quot;">​</a></h2><p>多键 PFCOUNT/PFMERGE 要求同槽。按活动分 tag 方便合并，也把活动热点集中到一个槽；分槽桶不能直接执行跨槽 PFMERGE，需要重新设计统计流水或汇总方式。副本延迟与 HLL 统计误差是两种不同误差来源。</p><p>一个键只在一个分片中，hash tag 控制相关键进入同一槽，不会把一个大键切开。副本读取通常是最终一致观察；操作后立即读到本次写入的需求应选主节点或明确的协调策略。</p><h2 id="client" tabindex="-1">8. Go 客户端与最佳实践 <a class="header-anchor" href="#client" aria-label="Permalink to &quot;8. Go 客户端与最佳实践 {#client}&quot;">​</a></h2><p>下面函数使用 <code>github.com/redis/go-redis/v9</code>，调用方提供 <code>context.Context</code> 和已配置认证、超时的 <code>*redis.Client</code>。</p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HyperLogLogExample</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">rdb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">uid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rdb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PFAdd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;learn:go:event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, uid).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Err</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, err</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rdb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PFCount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;learn:go:event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>PFCount 在 Go 中返回 int64，但“整数返回值”不代表精确统计。所有生产者必须使用相同 uid 规范，避免不同字符串表达同一用户。Pipeline 适合不同活动的独立更新；同一活动有多个批次时需明确何时读取最终结果。</p><p>普通 Pipeline 只是批量发送，不能充当事务；批次过大也会增加响应缓冲与延迟。对超时后的写入重试，需要根据幂等性判断，不能把“没收到响应”当成“没执行”。</p><h3 id="继续阅读" tabindex="-1">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读&quot;">​</a></h3><p><a href="/middleware/redis/base/basic/data-types">数据类型总览</a> · <a href="/middleware/redis/pro/practice/game-scenarios">游戏与通用后端实践</a> · <a href="/middleware/redis/base/basic/transactions">原子性基础</a>。</p><p>参考：<a href="https://github.com/redis/redis/tree/8.2.10/src/commands" target="_blank" rel="noopener noreferrer">Redis 8.2.10 命令定义</a>、<a href="https://github.com/redis/go-redis" target="_blank" rel="noopener noreferrer">go-redis</a>、<a href="https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/" target="_blank" rel="noopener noreferrer">集群规格</a>。</p>`,48)])])}const g=a(r,[["render",n]]);export{k as __pageData,g as default};
